  const old = JSON.stringify(oldVersionList(12));
  const s = fakeStorage({ [STORE_KEY]: old });
  store.load();
  s.setThrows = true;
  assert.equal(store.save(oldVersionList(13)), 'failed');
  assert.equal(s.data.get(STORE_KEY), old);
});

